     <script>
       const h = (strings, ...values) =>
         strings.reduce((output, chunk, index) => output + chunk + (values[index] ?? ""), "");

       function RadioOption({ id, name, value, label, checked = false }) {
         return h`
           <div class="radio-option">
             <input
               id="${id}"
               type="radio"
               name="${name}"
               value="${value}"
               ${checked ? "checked" : ""}
               required
             />
             <label for="${id}">${label}</label>
           </div>
         `;
       }

       function NotificationPreferencesForm() {
         return h`
           <section class="card" aria-labelledby="preferences-heading">
             <div class="card-inner">
               <form id="notification-form" class="form-field">
                 <fieldset aria-describedby="notification-help">
                   <legend id="preferences-heading">
                     How do you prefer to receive notifications?
                     <span class="required-mark" aria-hidden="true">*</span>
                   </legend>
                   <p class="help-text" id="notification-help">
                     Choose one option so we can tailor updates to your workflow.
                   </p>

                   <div class="radio-list">
                     ${RadioOption({
                       id: "notify-email",
                       name: "notification-preference",
                       value: "Email",
                       label: "Email"
                     })}
                     ${RadioOption({
                       id: "notify-sms",
                       name: "notification-preference",
                       value: "SMS",
                       label: "SMS"
                     })}
                     ${RadioOption({
                       id: "notify-push",
                       name: "notification-preference",
                       value: "Push Notifications",
                       label: "Push Notifications"
                     })}
                   </div>
                 </fieldset>

                 <div class="actions">
                   <button class="submit-button" type="submit">Save preferences</button>
                   <p class="status" id="form-status" aria-live="polite"></p>
                 </div>
               </form>
             </div>
           </section>
         `;
       }

       function App() {
         return h`
           <header class="page-header">
             <p class="eyebrow">Notification settings</p>
             <h1>Choose how you want to hear from us</h1>
             <p class="subhead">
               Set one preferred channel for product updates, reminders, and important alerts.
             </p>
           </header>
           ${NotificationPreferencesForm()}
         `;
       }

       document.getElementById("app").innerHTML = App();

       const form = document.getElementById("notification-form");
       const status = document.getElementById("form-status");

       form.addEventListener("submit", (event) => {
         event.preventDefault();

         const selected = form.querySelector('input[name="notification-preference"]:checked');

         if (!selected) {
           status.textContent = "Please choose a notification preference before saving.";
           return;
         }

         status.textContent = `Preference saved: ${selected.value}.`;
       });
